mapper.select:
SELECT 
FROM sessions s

    s.workspace_uuid = #{params.WorkspaceUUID}
    AND s.deleted_at IS NULL
    AND s.archived_at IS NULL
    AND s.agent_external_id = #{params.AgentExternalID}
    AND s.agent_version = #{params.AgentVersion}
    AND s.deployment_external_id = #{params.DeploymentID}

        AND EXISTS (
            SELECT 1 FROM session_resources sr
            WHERE sr.workspace_uuid = s.workspace_uuid
            AND sr.session_external_id = s.external_id
            AND sr.deleted_at IS NULL
            AND sr.resource_type = 'memory_store'
            AND (sr.payload->>'memory_store_id' = #{params.MemoryStoreID}
                OR sr.payload->>'id' = #{params.MemoryStoreID})
        )


        AND s.status IN
        #{status}

    AND s.created_at > #{params.CreatedAtGT}
    AND s.created_at >= #{params.CreatedAtGTE}
    AND s.created_at < #{params.CreatedAtLT}
    AND s.created_at <= #{params.CreatedAtLTE}

        AND (s.created_at, s.uuid)

            <
            >

        (#{params.Cursor.CreatedAt}, #{params.Cursor.UUID})


ORDER BY s.created_at
DESC, s.uuid DESCASC, s.uuid ASC
LIMIT #{params.FetchLimit}

SELECT 
FROM sessions
WHERE workspace_uuid = #{workspaceUUID}
AND external_id = #{sessionExternalID}
AND deleted_at IS NULL
FOR UPDATE

mapper.update:
UPDATE sessions
SET metadata = COALESCE(metadata, CAST('{}' AS jsonb))
        || CAST(#{params.MetadataPatch,sensitive=true} AS jsonb),
    updated_at = NOW()
WHERE organization_uuid = #{params.OrganizationUUID}
AND workspace_uuid = #{params.WorkspaceUUID}
AND external_id = #{params.SessionExternalID}
AND deleted_at IS NULL
